dmg.__function__:
({ talent }, dmg) => {
    let ret1 = dmg(talent.e['技能伤害'], 'e')
    let ret2 = dmg(talent.e['技能伤害'], 'e', false, 0, 'talent', { dynamicDmg: talent.e['战技伤害提高'] * 100 })
    let ret3 = dmg(talent.e['技能伤害'], 'e', false, 0, 'talent', { dynamicDmg: talent.e['战技伤害提高'] * 100 })
    return {
      dmg: ret1.dmg + ret2.dmg + ret3.dmg * 3,
      avg: ret1.avg + ret2.avg + ret3.avg * 3,
    }
  }

({ cons, talent }, dmg) => {
    let num = cons < 2 ? 14 : 21
    return dmg(talent.e['技能伤害'] + num * 4 / 100, 'e')
  }

({ cons, talent }, dmg) => {
    let num = cons < 2 ? 14 : 21
    return dmg(talent.e['相邻目标伤害'] + num * 4 / 100, 'e')
  }

({ talent, calc, attr, cons }, { basic }) => {
    let num = cons > 0 ? 30 / 100 : 0
    let primaryDmg = basic(calc(attr.hp) * (talent.e2['技能伤害'] + num), 'e')
    return {
      dmg: primaryDmg.dmg,
      avg: primaryDmg.avg
    }
  }

cpct.__function__:
({ calc, attr }) => {
      let num = Math.min(Math.floor(calc(attr.hp) - 4000) / 100, 40)
      if (num > 0) {
        return num * 1.2
      } else {
        return 0
      }
    }

dmg.__function__:
({ talent, cons }, dmg) => {
    const gluttony = cons >= 2 ? 18 : 12
    const times = Math.floor(gluttony / 4)
    return dmg(talent.t['追加攻击伤害'] + talent.q['额外伤害'] * times, 't')
  }

tCdmg.__function__:
({ cons }) => {
      const gluttony = cons >= 2 ? 18 : 12
      return 80 + 10 * gluttony
    }

dmg.__function__:
({ calc, attr, talent, cons, params }, dmg) => {
      let shieldVal = calc(attr.atk) * talent.t['护盾•百分比攻击'] + talent.t['护盾•固定值']
      if (cons >= 2 && params.isQ_Enhanced) {
        shieldVal *= 2
      }
      return dmg.shield(shieldVal)
    }

(ds, dmg) => {
      const { talent, calc, attr, params, cons, trees } = ds
      const comradeAtk = params.comradeAtk || 0
      const selfDmgValue = calc(attr.atk) * talent.q['追加攻击伤害']
      let comradePct = talent.q['附加伤害']
      if (cons >= 2) comradePct *= 2
      const comradeDmgValue = comradeAtk * comradePct
      const zhengrongDmgValue = trees['103'] ? comradeAtk * 0.40 : 0
      const finalSelfDmg = dmg.basic(selfDmgValue, 't')
      const finalComradeDmg = dmg.basic(comradeDmgValue + zhengrongDmgValue, 't') 
      return {
        dmg: finalSelfDmg.dmg + finalComradeDmg.dmg,
        avg: finalSelfDmg.avg + finalComradeDmg.avg,
      }
    }

(ds, dmg) => {
      const comradeAtk = ds.params.comradeAtk || 0
      const totalValue = comradeAtk * 3.30
      return dmg.basic(totalValue, 't')
    }

